// API Route: GET /api/reports/statistics
// Serves statistics reports generated by statisticsReport.ts (migrated from RPTSTA00.cbl)

import { NextResponse } from "next/server";
import { withErrorHandler, AppError } from "@/lib/errorHandler";
import { generateStatisticsReport } from "@/services/reporting/statisticsReport";
import type { ApiResponse, StatisticsMetrics } from "@/types";

export const GET = withErrorHandler(async (request: Request) => {
  const start = Date.now();
  const { searchParams } = new URL(request.url);

  const startDateParam = searchParams.get("startDate");
  const endDateParam = searchParams.get("endDate");
  const trendDaysParam = searchParams.get("trendDays");

  let startDate: Date | undefined;
  let endDate: Date | undefined;
  let trendDays: number | undefined;

  if (startDateParam) {
    startDate = new Date(startDateParam);
    if (isNaN(startDate.getTime())) {
      throw new AppError({
        message: "Invalid startDate parameter.",
        httpStatus: 400,
        severity: 1,
        errorCode: "BADDATE",
      });
    }
  }

  if (endDateParam) {
    endDate = new Date(endDateParam);
    if (isNaN(endDate.getTime())) {
      throw new AppError({
        message: "Invalid endDate parameter.",
        httpStatus: 400,
        severity: 1,
        errorCode: "BADDATE",
      });
    }
  }

  if (trendDaysParam) {
    trendDays = parseInt(trendDaysParam, 10);
    if (isNaN(trendDays) || trendDays < 1 || trendDays > 365) {
      throw new AppError({
        message: "Invalid trendDays parameter. Must be 1-365.",
        httpStatus: 400,
        severity: 1,
        errorCode: "BADPARM",
      });
    }
  }

  const report = await generateStatisticsReport({
    startDate,
    endDate,
    trendDays,
  });

  const response: ApiResponse<StatisticsMetrics> = {
    success: true,
    data: report,
    metadata: {
      generatedAt: new Date().toISOString(),
      processingTimeMs: Date.now() - start,
    },
  };

  return NextResponse.json(response);
});
